gx={'x':x,'x2':x*x,'x3':x**3,'sqx':np.sqrt(x),'1/x':1/x,'lnx':np.log(x),'expmx':np.exp(-x),'x4':x**4}
hv={'v':v,'v2':v*v,'v3':v**3,'sqv':np.sqrt(v),'1/v':1/v,'lnv':np.log(v),'expmv':np.exp(-v),'tanhv':np.tanh(v),'v|v|':v*np.abs(v),'v4':v**4}
def build(w):
    tf={'c':np.cos(w*t),'s':np.sin(w*t),'t':t,'1':np.ones_like(t)}
    F={}
    for a,fa in tf.items():
        for b,fb in gx.items(): F[a+'*'+b]=fa*fb
        for b,fb in hv.items(): F[a+'*'+b]=fa*fb
    for b,fb in gx.items():
        for c_,fc in hv.items(): F[b+'*'+c_]=fb*fc
    return F
def greedy(F,y,k=3):
    names=list(F); M=np.column_stack([F[n] for n in names]); sel=[]
    for _ in range(k):
        bestе=None
        for j in range(len(names)):
            if j in sel: continue
            X=np.column_stack([M[:,i] for i in sel+[j]]+[np.ones_like(y)])
            cc=np.linalg.lstsq(X,y,rcond=None)[0]; e=np.mean((y-X@cc)**2)
            if bestе is None or e<bestе[0]: bestе=(e,j)
        sel.append(bestе[1])
    X=np.column_stack([M[:,i] for i in sel]+[np.ones_like(y)]); cc=np.linalg.lstsq(X,y,rcond=None)[0]
    return np.mean((y-X@cc)**2)/np.var(y),[names[i] for i in sel]
